<?php if($pages>1): $query=$_GET; ?><nav class="pagination" data-infinite-pagination aria-label="Страници"><?php for($p=1;$p<=$pages;$p++): $query['page']=$p;$href='?'.http_build_query($query); ?><a class="<?= $p===$filters['page']?'current':'' ?>" href="<?= $view->e($href) ?>" <?= $p===$filters['page']?'aria-current="page"':'' ?> <?= $p===$filters['page']+1?'rel="next"':'' ?>><?= $p ?></a><?php endfor; ?></nav><?php endif; ?>
